package com.iminiapp.backend.dining.api;
import com.iminiapp.backend.dining.application.DiningReservationService;import com.iminiapp.backend.identity.web.CurrentPrincipal;import com.iminiapp.backend.shared.api.ApiResponse;import com.iminiapp.backend.shared.web.TraceIds;import jakarta.servlet.http.HttpServletRequest;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.List;import static com.iminiapp.backend.dining.api.DiningModels.*;
@RestController @RequestMapping("/api/v1/admin/dining") public class AdminDiningOperationController{private final DiningReservationService s;public AdminDiningOperationController(DiningReservationService s){this.s=s;}
 @GetMapping("/orders")public ApiResponse<List<ReservationResponse>> orders(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate startDate,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate endDate,@RequestParam(required=false)Long storeId,@RequestParam(required=false)String status,HttpServletRequest r){return ApiResponse.success(s.admin(startDate,endDate,storeId,status),TraceIds.from(r));}
 @GetMapping("/kitchen-tickets")public ApiResponse<List<KitchenTicketResponse>> tickets(@RequestParam(required=false)String station,@RequestParam(required=false)String status,HttpServletRequest r){return ApiResponse.success(s.tickets(station,status),TraceIds.from(r));}@PostMapping("/kitchen-tickets/{id}/status")public ApiResponse<KitchenTicketResponse> kitchen(@PathVariable long id,@RequestBody KitchenActionRequest b,HttpServletRequest r){return ApiResponse.success(s.kitchen(id,CurrentPrincipal.from(r),b),TraceIds.from(r));}
 @PostMapping("/verifications/consume")public ApiResponse<ReservationResponse> verify(@RequestBody VerifyRequest b,HttpServletRequest r){return ApiResponse.success(s.verify(CurrentPrincipal.from(r),b),TraceIds.from(r));}@PostMapping("/orders/{id}/delivering")public ApiResponse<ReservationResponse> delivering(@PathVariable long id,HttpServletRequest r){return ApiResponse.success(s.startDelivery(CurrentPrincipal.from(r),id),TraceIds.from(r));}@PostMapping("/orders/{id}/complete")public ApiResponse<ReservationResponse> complete(@PathVariable long id,HttpServletRequest r){return ApiResponse.success(s.complete(CurrentPrincipal.from(r),id),TraceIds.from(r));}
 @GetMapping("/reports/overview")public ApiResponse<OverviewResponse> overview(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate startDate,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate endDate,HttpServletRequest r){return ApiResponse.success(s.overview(startDate,endDate),TraceIds.from(r));}@GetMapping("/reports/dish-sales")public ApiResponse<List<DishSalesResponse>> sales(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate startDate,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate endDate,HttpServletRequest r){return ApiResponse.success(s.sales(startDate,endDate),TraceIds.from(r));}
 @GetMapping(value="/reports/orders.csv",produces="text/csv")public ResponseEntity<byte[]> csv(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate startDate,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate endDate,@RequestParam(required=false)Long storeId,@RequestParam(required=false)String status){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=dining-orders.csv").contentType(new MediaType("text","csv",java.nio.charset.StandardCharsets.UTF_8)).body(s.csv(startDate,endDate,storeId,status));}
}
